using Clock=chrono::steady_clock;
static long long nowms(){return chrono::duration_cast<chrono::milliseconds>(Clock::now().time_since_epoch()).count();}
static string lower(string s){for(char &c:s)if(c>='A'&&c<='Z')c+=32;return s;}
static string trim(string s){size_t a=0,b=s.size();while(a<b&&(s[a]==' '||s[a]=='\t'))a++;while(b>a&&(s[b-1]==' '||s[b-1]=='\t'))b--;return s.substr(a,b-a);}
static bool tokenchar(unsigned char c){return (c>='a'&&c<='z')||(c>='A'&&c<='Z')||(c>='0'&&c<='9')||(c!=0&&strchr("!#$%&'*+-.^_`|~",c));}
static bool number(const string&s,unsigned long long &n){if(s.empty())return false;n=0;for(unsigned char c:s){if(c<'0'||c>'9'||n>(ULLONG_MAX-(c-'0'))/10)return false;n=n*10+c-'0';}return true;}
