static bool utf8(const string&s){for(size_t i=0;i<s.size();){unsigned char c=s[i++];if(c<128)continue;int n;unsigned int x,minv;if(c>=0xc2&&c<=0xdf){n=1;x=c&31;minv=128;}else if(c>=0xe0&&c<=0xef){n=2;x=c&15;minv=2048;}else if(c>=0xf0&&c<=0xf4){n=3;x=c&7;minv=65536;}else return false;if(i+n>s.size())return false;while(n--){unsigned char d=s[i++];if((d&0xc0)!=0x80)return false;x=(x<<6)|(d&63);}if(x<minv||x>0x10ffff||(x>=0xd800&&x<=0xdfff))return false;}return true;}
