struct Request{string method,target,version,host,lang,forward;bool close=false,head=false,hasauth=false;};
struct Entry{shared_ptr<string> body;string headers,etag;long long expiry=0,life=0;list<string>::iterator pos;};
struct Conn{int fd=-1,up=-1,file=-1;string in,out,upsend,upin,upheaders,upetag,key;size_t os=0,bs=0,ups=0,upbodylen=0;off_t fileoff=0;size_t filesize=0;shared_ptr<string> body;shared_ptr<Entry> stale;Request req;int count=0,state=0,upstatus=0;bool closeafter=false,eof=false,upheadparsed=false,upcacheable=false;long long last=0,first=0,deadline=0,uplife=0;};
