static void delup(Conn&c){if(c.up>=0){epoll_ctl(ep,EPOLL_CTL_DEL,c.up,nullptr);ups.erase(c.up);close(c.up);c.up=-1;}}
static void destroy(int fd){auto it=conns.find(fd);if(it==conns.end())return;Conn&c=*it->second;delup(c);if(c.file>=0)close(c.file);epoll_ctl(ep,EPOLL_CTL_DEL,fd,nullptr);close(fd);conns.erase(it);}
static void mod(int fd,uint32_t events){epoll_event e{};e.events=events;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_MOD,fd,&e);}
static void add(int fd,uint32_t events){epoll_event e{};e.events=events;e.data.fd=fd;epoll_ctl(ep,EPOLL_CTL_ADD,fd,&e);}
static string reason(int s){switch(s){case 200:return "OK";case 201:return "Created";case 204:return "No Content";case 301:return "Moved Permanently";case 302:return "Found";case 304:return "Not Modified";case 400:return "Bad Request";case 403:return "Forbidden";case 404:return "Not Found";case 405:return "Method Not Allowed";case 408:return "Request Timeout";case 413:return "Payload Too Large";case 431:return "Request Header Fields Too Large";case 500:return "Internal Server Error";case 502:return "Bad Gateway";case 503:return "Service Unavailable";default:return "Response";}}
static void respond(Conn&c,int status,size_t len,const string&extra,shared_ptr<string> body=nullptr,int file=-1){c.state=1;c.out="HTTP/1.1 "+to_string(status)+" "+reason(status)+"\r\nContent-Length: "+to_string(len)+"\r\n"+extra+"Connection: "+(c.closeafter?"close":"keep-alive")+"\r\n\r\n";c.os=0;c.bs=0;c.body=c.req.head?nullptr:body;c.file=c.req.head?-1:file;if(c.req.head&&file>=0)close(file);c.fileoff=0;c.filesize=c.file>=0?len:0;c.deadline=nowms()+cfg.write;mod(c.fd,EPOLLOUT|EPOLLRDHUP);}
static void error(Conn&c,int status,bool force=true){delup(c);if(force)c.closeafter=true;respond(c,status,0,"");}
static vector<string> comma(const string&s){vector<string> r;size_t p=0;while(p<=s.size()){size_t q=s.find(',',p);if(q==string::npos)q=s.size();r.push_back(lower(trim(s.substr(p,q-p))));if(q==s.size())break;p=q+1;}return r;}
