static string mergeheaders(const string& oldh,const string& newh){unordered_set<string> names;size_t p=0;while(p<newh.size()){size_t e=newh.find("\r\n",p);if(e==string::npos)break;size_t c=newh.find(':',p);if(c<e)names.insert(lower(newh.substr(p,c-p)));p=e+2;}string h;p=0;while(p<oldh.size()){size_t e=oldh.find("\r\n",p);if(e==string::npos)break;size_t c=oldh.find(':',p);if(c<e&&!names.count(lower(oldh.substr(p,c-p))))h+=oldh.substr(p,e+2-p);p=e+2;}return h+newh;}
static void finishup(Conn&c){delup(c);if(c.upstatus==304&&c.stale){auto old=c.stale;string headers=mergeheaders(old->headers,c.upheaders),etag;bool allowed;long long life;cachepolicy(headers,allowed,life,etag);if(allowed&&c.upcacheable)store(c.key,old->body,headers,etag,min(life,c.uplife));else erasecache(c.key);respond(c,200,old->body->size(),headers,old->body);return;}auto b=make_shared<string>(c.upin.substr(0,c.upbodylen));size_t len=c.req.head?c.filesize:c.upbodylen;if(c.upstatus==204||c.upstatus==304)len=0;if(c.req.method=="GET"&&!c.req.hasauth){if(c.upstatus==200){bool allowed;long long life;string etag;cachepolicy(c.upheaders,allowed,life,etag);if(allowed&&c.upcacheable)store(c.key,b,c.upheaders,etag,min(life,c.uplife));else erasecache(c.key);}else erasecache(c.key);}respond(c,c.upstatus,len,c.upheaders,b);}
static void handleup(Conn&c,uint32_t ev){if(ev&EPOLLERR){error(c,502,false);return;}if(c.ups<c.upsend.size()){while(c.ups<c.upsend.size()){ssize_t n=send(c.up,c.upsend.data()+c.ups,c.upsend.size()-c.ups,MSG_NOSIGNAL);if(n>0){c.ups+=n;continue;}if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;if(n<0&&errno==EINTR)continue;error(c,502,false);return;}mod(c.up,EPOLLIN|EPOLLRDHUP);}
 if(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP)){char buf[16384];while(true){ssize_t n=recv(c.up,buf,sizeof(buf),0);if(n>0){c.upin.append(buf,n);if(!c.upheadparsed){if(c.upin.size()>65536&&c.upin.find("\r\n\r\n")==string::npos){error(c,502,false);return;}if(responsehead(c)&&c.upstatus<0){error(c,502,false);return;}}if(c.upheadparsed&&c.upin.size()>=c.upbodylen){finishup(c);return;}continue;}if(n==0){error(c,502,false);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)break;error(c,502,false);return;}}}
static void readclient(Conn&c){char buf[16384];while(c.state==0){size_t cap=cfg.headers+1;if(c.in.size()>=cap){processinput(c);return;}size_t want=min(sizeof(buf),cap-c.in.size());ssize_t n=recv(c.fd,buf,want,0);if(n>0){if(c.in.empty())c.first=nowms();c.in.append(buf,n);c.last=nowms();processinput(c);if(c.state!=0)return;continue;}if(n==0){c.eof=true;if(c.in.empty()){destroy(c.fd);return;}processinput(c);return;}if(errno==EINTR)continue;if(errno==EAGAIN||errno==EWOULDBLOCK)return;destroy(c.fd);return;}}
static void writeclient(Conn&c){while(c.os<c.out.size()){ssize_t n=send(c.fd,c.out.data()+c.os,c.out.size()-c.os,MSG_NOSIGNAL);if(n>0){c.os+=n;c.deadline=nowms()+cfg.write;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;destroy(c.fd);return;}if(c.file>=0){while((size_t)c.fileoff<c.filesize){ssize_t n=sendfile(c.fd,c.file,&c.fileoff,min((size_t)1048576,c.filesize-(size_t)c.fileoff));if(n>0){c.deadline=nowms()+cfg.write;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;destroy(c.fd);return;}close(c.file);c.file=-1;}if(c.body){while(c.bs<c.body->size()){ssize_t n=send(c.fd,c.body->data()+c.bs,c.body->size()-c.bs,MSG_NOSIGNAL);if(n>0){c.bs+=n;c.deadline=nowms()+cfg.write;continue;}if(n<0&&errno==EINTR)continue;if(n<0&&(errno==EAGAIN||errno==EWOULDBLOCK))return;destroy(c.fd);return;}}c.body.reset();if(c.closeafter){destroy(c.fd);return;}c.state=0;c.last=nowms();mod(c.fd,EPOLLIN|EPOLLRDHUP);if(!c.in.empty())processinput(c);}
int main(int argc,char**argv){signal(SIGPIPE,SIG_IGN);if(!loadconfig(argc,argv))return 1;rootfd=open(cfg.root.c_str(),O_RDONLY|O_DIRECTORY|O_CLOEXEC);if(rootfd<0)return 1;listenfd=socket(AF_INET,SOCK_STREAM|SOCK_NONBLOCK|SOCK_CLOEXEC,0);if(listenfd<0)return 1;int one=1;setsockopt(listenfd,SOL_SOCKET,SO_REUSEADDR,&one,sizeof(one));if(bind(listenfd,(sockaddr*)&cfg.listen,sizeof(cfg.listen))||listen(listenfd,4096))return 1;ep=epoll_create1(EPOLL_CLOEXEC);if(ep<0)return 1;add(listenfd,EPOLLIN);epoll_event events[512];long long next=nowms()+50;while(true){int n=epoll_wait(ep,events,512,50);if(n<0){if(errno==EINTR)continue;break;}for(int i=0;i<n;i++){int fd=events[i].data.fd;uint32_t ev=events[i].events;if(fd==listenfd){while(true){int c=accept4(fd,nullptr,nullptr,SOCK_NONBLOCK|SOCK_CLOEXEC);if(c<0){if(errno==EINTR)continue;break;}if(conns.size()>=cfg.maxconn){close(c);continue;}setsockopt(c,IPPROTO_TCP,TCP_NODELAY,&one,sizeof(one));auto x=make_unique<Conn>();x->fd=c;x->last=nowms();conns[c]=move(x);add(c,EPOLLIN|EPOLLRDHUP);}continue;}auto u=ups.find(fd);if(u!=ups.end()){auto it=conns.find(u->second);if(it!=conns.end())handleup(*it->second,ev);continue;}auto it=conns.find(fd);if(it==conns.end())continue;Conn&c=*it->second;if(ev&EPOLLERR){destroy(fd);continue;}if(c.state==0&&(ev&(EPOLLIN|EPOLLRDHUP|EPOLLHUP)))readclient(c);else if(c.state==1&&(ev&EPOLLOUT))writeclient(c);else if((ev&EPOLLHUP)&&c.state!=1)destroy(fd);}long long t=nowms();if(t>=next){vector<int> dead;for(auto&kv:conns){Conn&c=*kv.second;if(c.state==0){if(c.first&&t-c.first>=cfg.ht){c.req=Request();error(c,408);}else if(!c.first&&t-c.last>=cfg.idle)dead.push_back(c.fd);}else if(t>=c.deadline){if(c.state==2)error(c,502,false);else dead.push_back(c.fd);}}for(int fd:dead)destroy(fd);next=t+50;}}return 0;}
